import csv
import io


def parse_csv(raw_csv: str):
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    stream = io.StringIO(raw_csv, newline="")
    reader = csv.reader(stream, delimiter=";", quotechar='"', doublequote=True)
    columns = next(reader, None)
    if columns is None:
        return {"columns": [], "rows": []}

    rows = list(reader)
    width = max(17, len(columns), max((len(row) for row in rows), default=0))

    used_names = set(columns)
    for position in range(len(columns) + 1, width + 1):
        base = f"column_{position}"
        name = base
        suffix = 2
        while name in used_names:
            name = f"{base}_{suffix}"
            suffix += 1
        columns.append(name)
        used_names.add(name)

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
